{
  "name": "pack_ll_header",
  "confidence": "medium",
  "docstring": "Packs raw Bluetooth Low Energy link-layer header words into an internal packet descriptor, merging flags and length fields and computing scaled timing/length values.",
  "subsystem": "ble",
  "var_renames": {
    "v4": "raw_hdr_word",
    "v5": "dst_hdr_word0",
    "v6": "status_table_ptr",
    "v7": "hdr_len_shift",
    "v8": "dst_hdr_word1",
    "v9": "raw_hdr_qword_low",
    "v11": "status_word_ptr",
    "v12": "raw_hdr_byte10",
    "v14": "raw_hdr_word11",
    "v15": "dst_flag_bit2",
    "v16": "scale_factor",
    "v17": "scaled_raw_word11",
    "v18": "timing_constant",
    "v19": "scaled_byte10",
    "result": "status_flag"
  },
  "struct_hints": [
    {
      "offset": 0,
      "meaning": "first packed 16-bit header word with merged source and destination flags"
    },
    {
      "offset": 2,
      "meaning": "3-bit header subfield extracted from raw header bits 7-9"
    },
    {
      "offset": 4,
      "meaning": "single header flag extracted from raw header bit 6"
    },
    {
      "offset": 5,
      "meaning": "5-bit header subfield extracted from raw header bits 10-14"
    },
    {
      "offset": 7,
      "meaning": "byte copied from raw header offset 10"
    },
    {
      "offset": 8,
      "meaning": "16-bit header field copied from raw header offset 11"
    },
    {
      "offset": 12,
      "meaning": "derived 32-bit field from raw header offset 10, shifted by 8 or 10 depending on flags"
    },
    {
      "offset": 16,
      "meaning": "derived 32-bit field from raw header offset 11 shifted by the 5-bit header subfield"
    },
    {
      "offset": 24,
      "meaning": "32-bit raw header field copied from source offset 2"
    },
    {
      "offset": 28,
      "meaning": "32-bit raw header field copied from source offset 6"
    },
    {
      "offset": 41,
      "meaning": "byte copied from raw header offset 13"
    },
    {
      "offset": 48,
      "meaning": "scaled 32-bit estimate, likely derived length/timing value"
    }
  ]
}
